import json
d = json.load(open('submission/evaluation.json'))
print('questions', len(d['questions']), 'items', len(d['items']))
print('agg', d.get('aggregation'))
for dom, agg in d['domain_aggregations'].items():
    print(dom, 'weights', len(agg['weights']))
# verify items reference valid question ids
qids = {q['id'] for q in d['questions']}
iids = {i['id'] for i in d['items']}
assert qids == iids, 'mismatch'
# verify weights match items
for dom, agg in d['domain_aggregations'].items():
    for iid in agg['weights']:
        assert iid in qids
print('VALID manifest: 101 questions, 3 domains OK')
"",
